import{_ as s,o as n,c as t,a2 as e}from"./chunks/framework.XXezeKOl.js";const m=JSON.parse('{"title":"Transformer 的直觉理解","description":"不用公式，理解大模型\\"预测下一个 Token\\"和注意力机制，以及它们对 Agent 开发意味着什么。","frontmatter":{"title":"Transformer 的直觉理解","description":"不用公式，理解大模型\\"预测下一个 Token\\"和注意力机制，以及它们对 Agent 开发意味着什么。"},"headers":[],"relativePath":"guide/02-llm-basics/transformer.md","filePath":"guide/02-llm-basics/transformer.md","lastUpdated":null}'),l={name:"guide/02-llm-basics/transformer.md"};function r(o,a,i,p,u,d){return n(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="transformer-的直觉理解" tabindex="-1">Transformer 的直觉理解 <a class="header-anchor" href="#transformer-的直觉理解" aria-label="Permalink to &quot;Transformer 的直觉理解&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">学习目标</p><ul><li>理解大模型的本质：一个反复&quot;预测下一个 Token&quot;的函数</li><li>用直觉理解注意力（Attention）机制在做什么</li><li>知道训练、推理、预训练与指令微调分别是什么</li><li>能把这些原理和 Agent 开发中的实际现象对应起来</li></ul></div><p>做 Agent 开发不需要会推导 Transformer 的公式，但需要知道模型&quot;大概是怎么工作的&quot;。很多看起来奇怪的现象，比如模型会编造事实、长对话中忘掉前面的要求、同一个问题两次回答不一样，都能从原理里找到解释。这篇文章只讲直觉，不讲矩阵运算。</p><h2 id="大模型只做一件事-预测下一个-token" tabindex="-1">大模型只做一件事：预测下一个 Token <a class="header-anchor" href="#大模型只做一件事-预测下一个-token" aria-label="Permalink to &quot;大模型只做一件事：预测下一个 Token&quot;">​</a></h2><p>把大模型想成一个函数：输入一段文本，输出&quot;下一个 Token 是什么&quot;的概率分布。Token 是模型处理文本的最小单位，可以粗略理解为&quot;词或词的一部分&quot;，下一篇 <a href="/guide/02-llm-basics/tokens-context">Token 与上下文窗口</a> 会详细展开。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入:  &quot;北京是中国的&quot;</span></span>
<span class="line"><span>            │</span></span>
<span class="line"><span>            ▼</span></span>
<span class="line"><span>      ┌───────────┐</span></span>
<span class="line"><span>      │  大模型    │</span></span>
<span class="line"><span>      └───────────┘</span></span>
<span class="line"><span>            │</span></span>
<span class="line"><span>            ▼</span></span>
<span class="line"><span>输出概率:  首都 0.82 | 城市 0.06 | 政治 0.04 | ...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>模型选出一个 Token（比如&quot;首都&quot;），把它拼到输入末尾，再预测下一个，如此循环，直到生成结束标记或达到长度上限。这叫<strong>自回归生成</strong>（autoregressive generation）：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第 1 步: 北京是中国的            → 首都</span></span>
<span class="line"><span>第 2 步: 北京是中国的首都        → 。</span></span>
<span class="line"><span>第 3 步: 北京是中国的首都。      → &lt;结束&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>这个简单的循环带来几个直接后果：</p><ul><li><strong>输出是一个一个 Token 生成的</strong>。所以 API 可以流式返回（见 <a href="/guide/03-llm-api/streaming">流式响应实战</a>），输出越长耗时越长。</li><li><strong>每一步都是在概率中挑选</strong>。挑选方式由 temperature、top_p 等参数控制（见 <a href="/guide/02-llm-basics/sampling">采样参数</a>），这就是同一问题两次回答可能不同的原因。</li><li><strong>模型没有&quot;查数据库&quot;这一步</strong>。它生成的是&quot;看起来最合理的续写&quot;，而不是&quot;经过核实的事实&quot;。合理但错误的续写就是我们常说的幻觉（hallucination）。</li></ul><p>聊天、写代码、调用工具，在模型眼里都是&quot;续写文本&quot;。Chat API 里的 system、user、assistant 消息，最终会被拼成一段带特殊标记的长文本交给模型续写。Tool Calling 也一样：模型续写出一段符合约定格式的 JSON，由你的程序去真正执行。</p><h2 id="注意力-每个-token-都在-看-其他-token" tabindex="-1">注意力：每个 Token 都在&quot;看&quot;其他 Token <a class="header-anchor" href="#注意力-每个-token-都在-看-其他-token" aria-label="Permalink to &quot;注意力：每个 Token 都在&quot;看&quot;其他 Token&quot;">​</a></h2><p>预测下一个 Token 时，模型需要理解上下文。Transformer 的核心是<strong>注意力机制</strong>（Attention）：处理每个 Token 时，它会给前文中的每个 Token 打一个&quot;相关度&quot;分数，然后按分数加权汇总这些 Token 的信息。</p><p>看一个例子：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;小王把书借给了小李，因为他明天要考试。&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>处理 &quot;他&quot; 时，模型的注意力大致分布：</span></span>
<span class="line"><span>  小王 ████████░░  0.35</span></span>
<span class="line"><span>  小李 ██████████  0.45</span></span>
<span class="line"><span>  书   ██░░░░░░░░  0.08</span></span>
<span class="line"><span>  考试 ███░░░░░░░  0.12</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>&quot;他&quot;指谁需要结合整句话判断，注意力机制让模型在每一步都能动态决定&quot;现在该重点看哪些词&quot;。几个关键直觉：</p><ol><li><strong>多头注意力</strong>（Multi-Head Attention）：模型同时有很多组注意力，有的关注语法关系，有的关注指代，有的关注格式。每组叫一个&quot;头&quot;。</li><li><strong>层层堆叠</strong>：一个 Transformer 由几十层甚至上百层这样的结构叠起来。浅层更多处理词语和语法，深层逐渐形成更抽象的语义。</li><li><strong>只能看前面</strong>：生成式模型使用因果注意力（causal attention），每个 Token 只能看到它之前的内容，看不到&quot;未来&quot;。</li><li><strong>全部并行</strong>：与早期的 RNN 逐字处理不同，Transformer 可以并行处理整段输入。这是它能在海量数据上训练的关键原因。</li></ol><p>注意力的计算量随输入长度大约呈平方增长，所以上下文越长，推理越慢、越贵。这也是上下文窗口有上限的原因之一。</p><h2 id="位置信息" tabindex="-1">位置信息 <a class="header-anchor" href="#位置信息" aria-label="Permalink to &quot;位置信息&quot;">​</a></h2><p>注意力本身不关心顺序，&quot;狗咬人&quot;和&quot;人咬狗&quot;里的 Token 是一样的。所以模型会给每个 Token 附加位置信息（位置编码）。现代模型常用 RoPE 等相对位置编码方案，这也是厂商能把上下文窗口扩展到很长的技术基础之一。</p><p>开发中要知道的结论是：<strong>模型对长上下文中不同位置的信息，利用程度并不均匀</strong>。有研究发现模型更容易利用开头和结尾的信息，而中间部分容易被忽略（&quot;Lost in the Middle&quot;）。因此重要的指令放在 system prompt 开头或用户消息末尾，效果通常更稳定。</p><h2 id="模型是怎么-学会-的" tabindex="-1">模型是怎么&quot;学会&quot;的 <a class="header-anchor" href="#模型是怎么-学会-的" aria-label="Permalink to &quot;模型是怎么&quot;学会&quot;的&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌────────────┐    ┌──────────────┐    ┌────────────────┐</span></span>
<span class="line"><span>│  预训练     │ →  │  指令微调     │ →  │  偏好对齐       │</span></span>
<span class="line"><span>│ 海量文本    │    │ 问答示范数据  │    │ RLHF / 偏好优化 │</span></span>
<span class="line"><span>│ 学会续写    │    │ 学会听指令    │    │ 学会更有帮助、  │</span></span>
<span class="line"><span>│            │    │              │    │ 更安全          │</span></span>
<span class="line"><span>└────────────┘    └──────────────┘    └────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><ul><li><strong>预训练</strong>：在海量文本上反复做&quot;预测下一个 Token&quot;的练习。模型从中学到语言、知识和一定的推理模式。这一步得到的是&quot;基座模型&quot;（base model），擅长续写，但不一定听指令。</li><li><strong>指令微调</strong>（SFT）：用大量&quot;指令 → 理想回答&quot;的示范数据继续训练，模型学会以助手的方式回答。</li><li><strong>偏好对齐</strong>：通过人类或 AI 的偏好反馈继续优化，让回答更有帮助、更安全。工具调用、结构化输出这类能力也主要在微调阶段被专门强化。</li></ul><p>训练完成后，模型的参数（权重）就固定了。你调用 API 时只是在做<strong>推理</strong>（inference），模型不会因为你的对话而&quot;学习&quot;。这一点很重要：</p><ul><li>模型的知识停留在训练数据的截止时间（knowledge cutoff），需要新知识就得通过上下文提供，这就是 <a href="/guide/09-rag/overview">RAG</a> 的出发点。</li><li>模型本身没有记忆。多轮对话&quot;记得&quot;前文，是因为每次请求你都把历史消息重新发了一遍（见 <a href="/guide/03-llm-api/multi-turn">多轮对话与消息结构</a>）。跨会话的记忆需要你自己实现（见 <a href="/guide/08-memory/memory-types">记忆的分类</a>）。</li></ul><h2 id="这些原理对-agent-开发意味着什么" tabindex="-1">这些原理对 Agent 开发意味着什么 <a class="header-anchor" href="#这些原理对-agent-开发意味着什么" aria-label="Permalink to &quot;这些原理对 Agent 开发意味着什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>原理</th><th>实际现象</th><th>开发上的应对</th></tr></thead><tbody><tr><td>逐 Token 生成</td><td>输出越长越慢</td><td>用流式输出改善体验，控制 max_tokens</td></tr><tr><td>概率采样</td><td>同样输入结果不同</td><td>需要稳定时降低 temperature，做评估而不是只试一次</td></tr><tr><td>续写&quot;合理文本&quot;</td><td>幻觉、编造 API 名</td><td>用工具和检索提供事实，对输出做校验</td></tr><tr><td>注意力计算随长度增长</td><td>长上下文更贵、更慢</td><td>做上下文管理和压缩</td></tr><tr><td>位置利用不均</td><td>长对话中忘记早期指令</td><td>关键指令放开头或末尾，必要时重复</td></tr><tr><td>推理时权重不变</td><td>模型不会记住你</td><td>记忆、知识都要通过上下文注入</td></tr></tbody></table><p>可以说，Agent 开发的大部分工程工作，都是在&quot;一个无状态的、按概率续写文本的函数&quot;外面，搭建状态、工具、记忆和校验。</p><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><ul><li><strong>把模型当数据库</strong>：直接问模型某个库的最新版本号、某个 API 的参数，它会给出&quot;看起来对&quot;的答案。事实性信息应该来自工具或文档。</li><li><strong>以为模型会从对话中学习</strong>：用户纠正过一次，下次新会话模型依然会犯同样的错。需要把纠正写入提示词或记忆。</li><li><strong>以为上下文越长越好</strong>：把所有资料都塞进去，既贵又可能让关键信息&quot;淹没在中间&quot;。</li><li><strong>用一次测试结果下结论</strong>：采样带来随机性，改了提示词后跑一次&quot;变好了&quot;不代表真的变好了。参见 <a href="/guide/14-evaluation/why-evals">为什么评估是第一优先级</a>。</li></ul><h2 id="小测" tabindex="-1">小测 <a class="header-anchor" href="#小测" aria-label="Permalink to &quot;小测&quot;">​</a></h2><p><strong>1. 模型生成一段 500 Token 的回答，大致需要经过多少次&quot;预测下一个 Token&quot;？</strong></p><details class="details custom-block"><summary>查看答案</summary><p>大约 500 次。自回归生成每一步产出一个 Token，并把它拼回输入继续预测。这也是输出 Token 通常比输入 Token 更慢、单价更高的原因之一。</p></details><p><strong>2. 用户说&quot;我上周告诉过你我叫小明&quot;，但模型说不知道。最可能的原因是什么？</strong></p><details class="details custom-block"><summary>查看答案</summary><p>模型推理时权重不变，本身没有跨会话记忆。上周的对话没有被包含在这次请求的上下文里，模型自然无从得知。要实现这种能力，需要应用层把历史信息存储起来，并在请求时注入上下文。</p></details><p><strong>3. 注意力机制解决的核心问题是什么？</strong></p><details class="details custom-block"><summary>查看答案</summary><p>让模型在处理每个 Token 时，能动态决定上下文中哪些 Token 更相关，并汇总它们的信息。这让模型能处理指代、长距离依赖等问题，并且整段输入可以并行计算。</p></details><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="https://arxiv.org/abs/1706.03762" target="_blank" rel="noreferrer">Attention Is All You Need</a>：Transformer 原始论文</li><li><a href="https://arxiv.org/abs/2307.03172" target="_blank" rel="noreferrer">Lost in the Middle: How Language Models Use Long Contexts</a></li><li><a href="https://jalammar.github.io/illustrated-transformer/" target="_blank" rel="noreferrer">The Illustrated Transformer</a>：经典的图解文章</li><li>下一篇：<a href="/guide/02-llm-basics/tokens-context">Token 与上下文窗口</a></li></ul>`,40)])])}const b=s(l,[["render",r]]);export{m as __pageData,b as default};
